<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import BaseButton from '../../components/ui/BaseButton.vue'; import OtpInput from '../../components/onboarding/OtpInput.vue'; import { companyOnboardingService } from '../../services/companyOnboarding.service'; import { useCompanyOnboardingStore } from '../../stores/companyOnboarding'
const router = useRouter(); const store = useCompanyOnboardingStore(); const code = ref(''); const error = ref(''); const loading = ref(false)
async function verify(value = code.value) { if (value.length !== 6) { error.value = 'Informe os 6 dígitos.'; return }; loading.value = true; try { const response = await companyOnboardingService.verifyEmailOtp(value) as { verified?: boolean }; if (!response.verified) throw new Error('Código inválido.'); store.state.verification.emailVerified = true; store.nextStep(); router.push('/cadastro/revisao') } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Não foi possível validar o código.' } finally { loading.value = false } }
</script>
<template><section class="text-center"><h1 class="text-3xl font-medium tracking-tight sm:text-4xl">Confirme seu e-mail</h1><p class="mx-auto mt-5 max-w-md leading-7 text-neutral-600">Enviamos um código de 6 dígitos para <strong class="font-medium text-neutral-900">{{ store.state.company.email }}</strong>.</p><div class="mt-10"><OtpInput v-model="code" :disabled="loading" @complete="verify" /><p v-if="error" class="mt-4 text-sm text-red-600">{{ error }}</p></div><BaseButton class="mt-8 min-h-[56px] w-full text-base sm:min-h-[68px] sm:text-lg" :disabled="loading" @click="verify">{{ loading ? 'Validando...' : 'Confirmar e-mail' }}</BaseButton><button type="button" class="mt-6 text-sm underline underline-offset-2" @click="companyOnboardingService.sendEmailOtp">Reenviar código</button></section></template>
